wrapper_template:
case "${1:-}" in
  workers)
    wrangler deployments list 2>/dev/null | head -n "$MAX_LINES" || curl -s -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/workers/scripts" | head -n "$MAX_LINES"
    ;;
  kv-ls)
    wrangler kv namespace list 2>/dev/null | head -n "$MAX_LINES" || curl -s -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/storage/kv/namespaces" | head -n "$MAX_LINES"
    ;;
  kv-get)
    [ -z "${3:-}" ] && { echo "Usage: cloudflare.sh kv-get <namespace_id> <key>" >&2; exit 1; }
    wrangler kv key get --namespace-id="$2" "$3" 2>/dev/null || curl -s -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/storage/kv/namespaces/$2/values/$3"
    ;;
  kv-put)
    [ -z "${4:-}" ] && { echo "Usage: cloudflare.sh kv-put <namespace_id> <key> <value>" >&2; exit 1; }
    wrangler kv key put --namespace-id="$2" "$3" "$4" 2>/dev/null || curl -s -X PUT -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" -d "$4" "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/storage/kv/namespaces/$2/values/$3"
    ;;
  r2-ls)
    wrangler r2 bucket list 2>/dev/null | head -n "$MAX_LINES" || curl -s -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/r2/buckets" | head -n "$MAX_LINES"
    ;;
  r2-ls-bucket)
    [ -z "${2:-}" ] && { echo "Usage: cloudflare.sh r2-ls-bucket <bucket>" >&2; exit 1; }
    wrangler r2 object list "$2" 2>/dev/null | head -n "$MAX_LINES"
    ;;
  d1-ls)
    wrangler d1 list 2>/dev/null | head -n "$MAX_LINES" || curl -s -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" "https://api.cloudflare.com/client/v4/accounts/$CLOUDFLARE_ACCOUNT_ID/d1/database" | head -n "$MAX_LINES"
    ;;
  d1-query)
    [ -z "${3:-}" ] && { echo "Usage: cloudflare.sh d1-query <database> <sql>" >&2; exit 1; }
    wrangler d1 execute "$2" --command="$3" 2>/dev/null | head -n "$MAX_LINES"
    ;;
  dns-ls)
    [ -z "${2:-}" ] && { echo "Usage: cloudflare.sh dns-ls <zone_id>" >&2; exit 1; }
    curl -s -H "Authorization: Bearer $CLOUDFLARE_API_TOKEN" "https://api.cloudflare.com/client/v4/zones/$2/dns_records" | head -n "$MAX_LINES"
    ;;
